package vn.cozynest.booking.application.service;

import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * Resolves canonical landlord user UUIDs alongside legacy numeric demo IDs (1..6)
 * and deterministic numeric hash IDs generated by listing-service.
 */
public final class LandlordIdentityResolver {

    private static final Map<String, String> LEGACY_NUM_TO_UUID = Map.of(
            "1", "u-landlord-01",
            "2", "u-landlord-02",
            "3", "u-landlord-03",
            "4", "u-landlord-04",
            "5", "u-landlord-05",
            "6", "u-landlord-06"
    );

    private static final Map<String, String> LEGACY_UUID_TO_NUM = Map.of(
            "u-landlord-01", "1",
            "u-landlord-02", "2",
            "u-landlord-03", "3",
            "u-landlord-04", "4",
            "u-landlord-05", "5",
            "u-landlord-06", "6"
    );

    private LandlordIdentityResolver() {
    }

    public static String normalizeLegacy(String landlordId) {
        if (landlordId == null) {
            return null;
        }
        String trimmed = landlordId.trim();
        return LEGACY_NUM_TO_UUID.getOrDefault(trimmed, trimmed);
    }

    public static Set<String> resolveAliases(String landlordId) {
        Set<String> aliases = new LinkedHashSet<>();
        if (landlordId == null || landlordId.isBlank()) {
            return aliases;
        }
        String trimmed = landlordId.trim();
        aliases.add(trimmed);

        String legacyUuid = LEGACY_NUM_TO_UUID.get(trimmed);
        if (legacyUuid != null) {
            aliases.add(legacyUuid);
        }
        String legacyNum = LEGACY_UUID_TO_NUM.get(trimmed);
        if (legacyNum != null) {
            aliases.add(legacyNum);
        }

        if (!trimmed.matches("^\\d+$")) {
            long hash = Math.abs((long) trimmed.hashCode());
            long numericId = hash > 100 ? hash : hash + 1000L;
            aliases.add(String.valueOf(numericId));
        }
        return aliases;
    }

    public static boolean matches(String expected, String actual) {
        if (expected == null || actual == null) {
            return false;
        }
        if (expected.trim().equals(actual.trim())) {
            return true;
        }
        Set<String> expectedAliases = resolveAliases(expected);
        Set<String> actualAliases = resolveAliases(actual);
        for (String alias : expectedAliases) {
            if (actualAliases.contains(alias)) {
                return true;
            }
        }
        return false;
    }
}
